  position:relative; z-index:0;
}

/* 语音 / 贴纸按钮盖在输入框上面 */
.input-btns-right,
.input-btn-mic,
.input-btn-sticker{ z-index:2; }

/* ===== 底栏 · 去上边框线 + 灰圆底加号 / # ===== */
:root{
  --nj-btn-bg:#f2f2f2;    /* 灰圆底 */
  --nj-btn-ic:#000;       /* 加号和 # 的颜色 */
  --nj-btn-size:32px;     /* 圆底直径 */
