  display:none !important;
}
.chat-detail-screen :is(.input-btn-plus,.input-btn-ai)::before{
  content:""; display:block; flex:none;
  background:var(--nj-btn-ic);
  -webkit-mask:var(--ic) center/contain no-repeat;
          mask:var(--ic) center/contain no-repeat;
}

.chat-detail-screen .input-btn-plus{
  translate:0 -4px !important;   /* 负数往上，改这个数调高度 */
