.gift-ig-container .gift-ig-box.status-opened::after { background: var(--gift-card-bg-opened) !important; }
.gift-ig-container.msg-gift-card:has(.gift-ig-box.status-closed){ background: var(--gift-card-bg-closed) !important; }
.gift-ig-container.msg-gift-card:has(.gift-ig-box.status-closed)::before{ color: var(--gift-text-color-closed) !important; -webkit-text-fill-color: var(--gift-text-color-closed) !important; }
.gift-ig-container.msg-gift-card:has(.gift-ig-box.status-closed) .gift-ig-preview{ display: none !important; }
