.gift-ig-container.msg-gift-card:has(.gift-ig-box.status-opened) .gift-ig-preview-text > span { font-size: 0 !important; color: transparent !important; }
.gift-ig-container.msg-gift-card:has(.gift-ig-box.status-opened) .gift-ig-preview-text > span::before{
