/* ========================================================
   ✅ 输入文字时：右侧仅留微信绿底“发送”按键，隐藏笑脸
   ======================================================== */

/* 1. 输入文字时，胶囊只需缩短给出一个发送键的距离 */
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) {
    margin-right: 70px !important;    /* 👈 核心：从 98px 减小到 56px，只留出一个按键位 */
    transition: all 0.25s ease-in-out !important;
}

