.send-btn-custom {
    position: absolute;
    right: 10px;
    margin-bottom: 2px !important;
    z-index: 2;
    width: 48px;
    height: 32px;
    border-radius: 0;
    color: transparent !important;
    background: transparent !important;
    cursor: pointer;
